args.sql:
DELETE FROM transportation_assets
WHERE housetag IN (
    SELECT housenum FROM households
    WHERE socioeconomic->>'Income_Bracket' IS NULL
);

WITH deleted AS (
    DELETE FROM transportation_assets
    WHERE housetag IN (
        SELECT housenum FROM households
        WHERE socioeconomic->>'Income_Bracket' IS NULL
    )
    RETURNING *
)
SELECT COUNT(*) AS removed_count FROM deleted;

SELECT locregion, COUNT(*) AS total, SUM(CASE WHEN socioeconomic->>'Income_Bracket' IS NULL THEN 1 ELSE 0 END) AS null_income, 
       ROUND(100.0 * SUM(CASE WHEN socioeconomic->>'Income_Bracket' IS NULL THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_null
FROM households GROUP BY locregion;
